const input = $input.first().json;
// The Webhook node (v2) nests the POSTed envelope under .body
const body = (input.body && typeof input.body === 'object' && input.body.event) ? input.body : input;
const event = (body.event || 'unknown').trim();
const data      = body.data      || {};
const task      = data.task      || {};
const plan      = data.plan      || {};
const milestone = data.milestone || {};
const pulse     = data.pulse     || {};
const team_id   = task.team_id  || plan.team_id  || data.team_id  || '';
const title     = task.title    || plan.title    || milestone.title || event;
let teamChatMap = {};
try { teamChatMap = JSON.parse($env.TEAM_TELEGRAM_CHAT_IDS || '{}'); } catch (_) { teamChatMap = {}; }
const chat_id   = team_id ? (teamChatMap[team_id] || '') : '';
const actor     = data.actor    || data.triggered_by || '';
let severity = 'info';
if (event === 'ramp.stuck')         severity = data.severity || 'high';
if (event === 'task.needs_changes') severity = 'medium';
if (event === 'onboarding.overdue') severity = 'medium';
if (event === 'task.overdue')       severity = 'medium';
return [{ json: { event, team_id, chat_id, title, actor, severity, task, plan, milestone, pulse, raw: body, received_at: new Date().toISOString() } }];

const item = $input.first().json;
const event = item.event;

const iconMap = {
  'onboarding.started':        '🚀',
  'onboarding.completed':      '🎉',
  'onboarding.step_completed': '✅',
  'onboarding.overdue':        '⏰',
  'task.created':              '📝',
  'task.submitted':            '📤',
  'task.completed':            '✅',
  'task.approved':             '✔️',
  'task.needs_changes':        '✏️',
  'task.overdue':              '⏰',
  'task.reopened':             '🔄',
  'ramp.started':              '🏁',
  'ramp.milestone_reached':    '🏆',
  'ramp.completed':            '🎓',
  'ramp.stuck':                '🚨',
  'pr.opened':                 '📬',
  'pr.review_requested':       '👀',
  'pr.merged':                 '🔀',
  'pr.closed':                 '🚫'
};

const icon = iconMap[event] ||
  (event.startsWith('onboarding') ? '👤' :
   event.startsWith('task')       ? '🔔' :
   event.startsWith('ramp')       ? '📈' :
   event.startsWith('pr')         ? '🔀' : '📦');

const critical = event === 'ramp.stuck';
const urgent   = !critical && ['task.needs_changes','onboarding.overdue','task.overdue'].includes(event);

let header;
if (critical)    header = '🚨 *URGENT — ' + event + '*';
else if (urgent) header = '⚠️ ' + icon + ' `' + event + '`';
else             header = icon + ' `' + event + '`';

const lines = [header, '*' + item.title + '*', ''];
if (item.team_id)                    lines.push('👥 Team: `' + item.team_id + '`');
if (item.actor)                      lines.push('👤 By: ' + item.actor);
if (item.severity && item.severity !== 'info') lines.push('🔴 Severity: *' + item.severity + '*');
if (item.task && item.task.task_id)  lines.push('🔖 Task: `' + item.task.task_id + '`');
if (item.plan && item.plan.id)       lines.push('📋 Plan: `' + item.plan.id + '`');
if (item.milestone && item.milestone.id) lines.push('🏁 Milestone: `' + item.milestone.id + '`');
if (critical) lines.push('', '_Open Onramp → Ramp view to intervene._');
lines.push('', '_' + item.received_at.slice(0,19).replace('T',' ') + ' UTC · Onramp_');

const chatId = ($env && $env.TELEGRAM_CHAT_ID) ? $env.TELEGRAM_CHAT_ID : '@your_channel';
return [{ json: { chat_id: chatId, text: lines.join('\n') } }];
